INSERT INTO public.fuentes (fuente_id, nombre, organismo, tipo, url, fecha_descarga, hash, archivo_raw, notas) VALUES
  ('aluar-eeff-2025', 'Memoria y Estados Financieros: 56° Ejercicio Económico (al 30/06/2025 y 30/06/2024)', 'Aluar Aluminio Argentino S.A.I.C. / CNV (auditado por PwC)', 'empresa', 'https://cdn.aluar.com.ar/assets/uploads/EEFF_Aluar_Ejercicio_2024_2025_4_T_7869bb3511.pdf', '2026-11-24', 'sha256:3ee6b54bf52a0a4e543e8be2d0c23d7399425b274971ae097867aee312233901', 'data/raw/aluar_eeff_2024_2025.pdf', 'Presentación formal ante CNV; contiene serie 5 ejercicios de producción en electrólisis y consumo eléctrico real medido en Puerto Madryn.'),
  ('aluar-web-institucional', 'Portal institucional y cifras operativas (Aluar)', 'Aluar Aluminio Argentino S.A.I.C.', 'empresa', 'https://www.aluar.com.ar/', '2026-11-24', 'sha256:a48420cd0884320a8a077268515d54811636d964ef983048fd8e231e56362496', 'data/raw/aluar_institucional.html', 'Capacidad instalada de aluminio primario (460.000 t/año) y etapas operativas en Puerto Madryn.'),
  ('aluar-como-producimos', 'Etapas del proceso de aluminio primario y elaborado (Aluar)', 'Aluar Aluminio Argentino S.A.I.C.', 'empresa', 'https://www.aluar.com.ar/aluminio/como-producimos', '2026-11-24', 'sha256:d0194264776114c118767e9f54fd7567d491b3d041357dbc2254231c0269cf58', 'data/raw/aluar_como_producimos.html', 'Descripción operativa de recepción portuaria, fabricación de ánodos, electrólisis y solidificación.'),
  ('indec-comex-aluminio-2024', 'Series de Tiempo INDEC: comercio exterior de aluminio y sus manufacturas (162.1 / 163.1 / 164.1)', 'INDEC / datos.gob.ar', 'oficial', 'https://apis.datos.gob.ar/series/api/series/?ids=162.1_XUMINIORAS_0_0_23,163.1_MUMINIORAS_0_0_23,164.1_SLUMINIRAS_0_0_24&start_date=2019-01-01&format=csv', '2026-11-24', 'sha256:1039267cff39cb3a5093f274e2ceeeab4a8f6ab80eb65b59393f4ca4a700f513', 'data/raw/datosgob_indec_aluminio_comex_anual.csv', 'Capítulo 76 NCM en millones de USD anuales (2019 a 2024).'),
  ('uncomtrade-ar-alumina-2023', 'UN Comtrade: importaciones de Argentina HS 281820 (Alúmina) y HS 7601 (Aluminio en bruto) 2023', 'UN Comtrade (Naciones Unidas)', 'oficial', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=32&period=2023&partnerCode=0&partner2Code=0&customsCode=C00&motCode=0&cmdCode=7601,281820', '2026-11-24', 'sha256:491e62a104cd961eb6d9aa058bb0a78e170f4ba684eb8cc1dd2196af9ea8a48e', 'data/raw/uncomtrade_ar_7601_281820_2023.json', 'Verifica importación de alúmina calcinada (855.972 t) como insumo crítico.'),
  ('uncomtrade-ar-alumina-2024', 'UN Comtrade: importaciones de Argentina HS 281820 (Alúmina) y HS 7601 (Aluminio en bruto) 2024', 'UN Comtrade (Naciones Unidas)', 'oficial', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=32&period=2024&partnerCode=0&partner2Code=0&customsCode=C00&motCode=0&cmdCode=7601,281820', '2026-11-24', 'sha256:db1674273b3b721a1421315ff8b7f301851654f7b2431b578d65e80bd35b19d8', 'data/raw/uncomtrade_ar_7601_281820_2024.json', 'Verifica importación de alúmina calcinada (871.523 t) y aluminio en bruto (4.453 t).'),
  ('ipcc-2006-v3-ch4-aluminio', '2006 IPCC Guidelines for National Greenhouse Gas Inventories (Vol. 3, Cap. 4.4 Primary Aluminium Production)', 'IPCC (Intergovernmental Panel on Climate Change)', 'tecnica', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/3_Volume3/V3_4_Ch4_Metal_Industry.pdf', '2026-11-24', 'sha256:d340e9a8c425cf441429db10a83ccd821988881faf1e0be26dd5eacac56fe6fe', 'data/raw/ipcc_2006_v3_ch4_metal_industry.pdf', 'Reacción global balanceada Hall-Héroult, baño de criolita, factor CO2 Prebake (1,6 t CO2/t Al) y parámetros de PFCs.'),
  ('usgs-mcs-2025-bauxita', 'Mineral Commodity Summaries 2025: Bauxite and Alumina', 'U.S. Geological Survey (USGS)', 'oficial', 'https://pubs.usgs.gov/periodicals/mcs2025/mcs2025-bauxite-alumina.pdf', '2026-11-24', 'sha256:f37ce33c9b54976deb3ed22571fd2dfaa1f7c19dff174ff62b73105b0d81f189', 'data/raw/usgs_mcs2025_bauxite_alumina.pdf', 'Relación técnica bauxita -> alúmina -> aluminio (4 t bauxita -> 2 t alúmina -> 1 t Al) y clasificación HS 2818.20.'),
  ('ejemplo-fuente-01', '[EJEMPLO] Marcador territorial demostrativo para cadenas MVP pendientes de Etapa 6', 'Atlas Químico AR (Plan MVP)', 'ejemplo', 'https://example.org/atlas-quimico-ar/mvp-pendiente', '2026-11-24', 'sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'data/sheets/', 'Usado únicamente para señalar las 6 cadenas pendientes de carga oficial en Etapa 6.')
