INSERT INTO public.procesos (proceso_id, producto_id, nombre, ruta_tecnologica, reaccion_global, energia_especifica_valor, energia_especifica_estado, energia_especifica_unidad, descripcion, anio, fuente_id, cita_ubicacion, confianza) VALUES
  ('aluminio-hall-heroult', 'aluminio', 'Producción de aluminio primario (Hall-Héroult)', 'Alúmina calcinada importada (proceso Bayer en origen) + ánodos precocidos de carbono -> reducción electrolítica en criolita fundida -> fundición y solidificación', '2 Al2O3 + 3 C -> 4 Al + 3 CO2', 14.2, 'dato', 'MWh/t Al', 'Cadena completa en Puerto Madryn (Chubut): 6.324.443 MWh consumidos en electrólisis para 445.327 t de aluminio líquido (14,20 MWh/t Al en electrólisis; 15,06 MWh/t Al considerando toda la planta) durante el ejercicio finalizado el 30/06/2025.', 2025, 'aluar-eeff-2025', 'Memoria 2025 pág. 3 (6.324.443 MWh electrólisis / 445.327 t aluminio líquido)', 'alta')
INSERT INTO public.pasos_proceso (paso_id, proceso_id, orden, nombre, tipo_paso, reaccion_balanceada, temperatura_c, presion_bar, reactivos, productos, insumos, subproductos, energia_valor, energia_estado, energia_unidad, descripcion, pos_x, pos_y, anio, fuente_id, cita_ubicacion, confianza) VALUES
  ('al-p1-bayer-origen', 'aluminio-hall-heroult', 1, 'Refinación Bayer en origen (importación)', 'materia_prima', '2 Al(OH)3 -> Al2O3 + 3 H2O', '1000-1100', '1.0', '[{"especie":"Bauxita seca","cantidad":4,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Al2O3 (alúmina calcinada)","cantidad":1.96,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"NaOH (digestión Bayer en origen)","cantidad":null,"unidad":"reciclo"}]'::jsonb, '[{"especie":"Lodo rojo (en país de origen)","cantidad":null,"unidad":"residuo"}]'::jsonb, NULL, 'sin_datos', NULL, 'Argentina no produce bauxita ni alúmina a escala primaria: importa el 100% de la alúmina calcinada (HS 2818.20, 871.523 t en 2024 según UN Comtrade). Regla general USGS: ~4 t de bauxita seca producen ~2 t de alúmina para obtener 1 t de aluminio.', 20, 170, 2025, 'usgs-mcs-2025-bauxita', 'USGS MCS 2025 Bauxite and Alumina pág. 43 nota 1 y UN Comtrade HS 281820 (2024)', 'alta'),
  ('al-p2-recepcion-storni', 'aluminio-hall-heroult', 2, 'Recepción portuaria y silos (Muelle Storni)', 'preparacion', NULL, '15-30', '1.0', '[{"especie":"Al2O3 importada","cantidad":1.96,"unidad":"t/t Al"},{"especie":"Coque calcinado y brea","cantidad":0.45,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Al2O3 en silos","cantidad":1.96,"unidad":"t/t Al"},{"especie":"Coque y brea en silos","cantidad":0.45,"unidad":"t/t Al"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', NULL, 'Descarga marítima de alúmina, coque de petróleo calcinado y brea mediante cinta transportadora en el Sitio 1 del Muelle Almirante Storni hacia los silos de la planta de Puerto Madryn.', 340, 170, 2025, 'aluar-como-producimos', 'aluar.com.ar/aluminio/como-producimos paso 1 y Memoria 2025 pág. 7', 'alta'),
  ('al-p3-planta-anodos', 'aluminio-hall-heroult', 3, 'Fabricación y cocción de ánodos precocidos', 'preparacion', NULL, '1100-1200', '1.0', '[{"especie":"Coque de petróleo calcinado y brea","cantidad":0.45,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Ánodos precocidos de carbono (C)","cantidad":0.43,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Coque de empaque (packing coke)","cantidad":0.015,"unidad":"t/t ánodo"}]'::jsonb, '[{"especie":"Volátiles de brea (captados y quemados)","cantidad":null,"unidad":"emisión tratada"}]'::jsonb, NULL, 'sin_datos', NULL, 'Molienda, mezclado de coque y brea, compactación de bloques verdes, horneado de cocción y envarillado para conducción eléctrica hacia las cubas electrolíticas. IPCC Table 4.11-4.13 documenta cenizas (0,4%), azufre (2%) y coque de empaque (0,015 t/t ánodo).', 670, 20, 2025, 'aluar-como-producimos', 'aluar.com.ar/aluminio/como-producimos paso 2 e IPCC 2006 Vol. 3 pág. 4.46-4.48', 'alta'),
  ('al-p4-electrolisis-hall-heroult', 'aluminio-hall-heroult', 4, 'Reducción electrolítica Hall-Héroult', 'reaccion', '2 Al2O3 + 3 C -> 4 Al + 3 CO2', '950-970', '1.0', '[{"especie":"Al2O3 (alúmina calcinada)","cantidad":1.96,"unidad":"t/t Al"},{"especie":"C (ánodos precocidos)","cantidad":0.43,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Al (aluminio líquido, pureza hasta 99,86%)","cantidad":1,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Na3AlF6 (criolita fundida ~80% baño)","cantidad":null,"unidad":"baño electrolítico"},{"especie":"Electricidad CC (Futaleufú + térmica + eólica)","cantidad":14.2,"unidad":"MWh/t Al"},{"especie":"O2 atmosférico (oxidación secundaria de ánodos)","cantidad":null,"unidad":"aire ambiente"}]'::jsonb, '[{"especie":"CO2 de proceso (factor Prebake IPCC)","cantidad":1.6,"unidad":"t/t Al"},{"especie":"Gases fluorados y PFCs (CF4/C2F6)","cantidad":0.00044,"unidad":"t/t Al"}]'::jsonb, 14.2, 'dato', 'MWh/t Al', 'Etapa central en cubas electrolíticas de ánodos precocidos. En FY 2024-2025 Puerto Madryn produjo 445.327 t de aluminio líquido consumiendo 6.324.443 MWh en electrólisis (14,20 MWh/t Al). Mínimo estequiométrico: 1,89 t Al2O3/t Al y 0,334 t C/t Al.', 670, 250, 2025, 'aluar-eeff-2025', 'Memoria 2025 pág. 3 (6.324.443 MWh / 445.327 t) e IPCC 2006 Vol. 3 pág. 4.43 y 4.47-4.54', 'alta'),
  ('al-p5-tratamiento-gases', 'aluminio-hall-heroult', 5, 'Tratamiento de gases (GTC) y emisiones', 'emision', NULL, '80-120', '1.0', '[{"especie":"Gases de cuba (CO2, HF, PFCs)","cantidad":1.6,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Alúmina fluorada reciclada a cubas","cantidad":null,"unidad":"reciclo"}]'::jsonb, '[{"especie":"Alúmina fresca (lecho adsorbente)","cantidad":null,"unidad":"contacto gas-sólido"}]'::jsonb, '[{"especie":"CO2 emitido a atmósfera (Tier 1 Prebake)","cantidad":1.6,"unidad":"t/t Al"},{"especie":"CF4 + C2F6 (efectos anódicos, Tier 1 CWPB)","cantidad":0.00044,"unidad":"t/t Al"}]'::jsonb, NULL, 'sin_datos', NULL, 'Los centros de tratamiento capturan fluoruros sobre alúmina fresca y la reinyectan a las cubas (reciclo cerrado). El CO2 de consumo anódico (1,6 t CO2/t Al según IPCC Table 4.10) y trazas de PFCs (0,4 kg CF4/t y 0,04 kg C2F6/t, Table 4.15) constituyen las emisiones directas de proceso.', 1020, 20, 2006, 'ipcc-2006-v3-ch4-aluminio', 'IPCC 2006 Vol. 3 Cap. 4.4 Table 4.10 pág. 4.47 y Table 4.15 pág. 4.54', 'alta'),
  ('al-p6-fundicion-colada', 'aluminio-hall-heroult', 6, 'Fundición, aleación y solidificación', 'producto', NULL, '700-740', '1.0', '[{"especie":"Al (aluminio líquido)","cantidad":1,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Lingotes puros, barrotes, lingotes T, alambrón y placas","cantidad":0.994,"unidad":"t/t Al"}]'::jsonb, '[{"especie":"Energía resto de planta (fundición, ánodos, aux.)","cantidad":0.86,"unidad":"MWh/t Al"}]'::jsonb, '[{"especie":"Escoria / mermas de fundición","cantidad":0.006,"unidad":"t/t Al"}]'::jsonb, 0.86, 'dato', 'MWh/t Al', 'Ajuste de composición, aleación y colada en hornos de fundición. En FY 2024-2025 se solidificaron 425.409 t (lingotes puros 140.997 t, barrotes 122.857 t, lingotes T 103.457 t, alambrón 40.287 t, aleados 6.901 t, placas 6.400 t, zincalum 4.510 t) más 17.028 t de despacho líquido.', 1020, 250, 2025, 'aluar-eeff-2025', 'Memoria 2025 pág. 3 (442.437 t solidificado+líquido y 382.466 MWh resto de planta)', 'alta')
INSERT INTO public.conexiones_proceso (conexion_id, proceso_id, origen_paso_id, destino_paso_id, corriente_nombre, tipo_corriente, flujo_valor, flujo_estado, flujo_unidad, anio, fuente_id, cita_ubicacion, confianza) VALUES
